save(135,dict(paragraphs=["Gargi Saha is a poet whose collections include The Muse in My Salad Days (2000) and Letters to Him (2012). Reviewing the latter, Ramesh Anand describes its linked poems as an extended dialogue of prayer, questioning and gratitude. Her poetry has also appeared in Literary Vibes.","Her Kabita Live contributions find expressive possibilities in everyday sights and sounds. ‘Onomatopoeia’ gathers a world of rustling, humming and calls, while ‘The Simple Pleasures of Life’ attends to birds, rain and green landscapes. ‘Ineffable Altruism’ asks what people owe the earth that feeds them; ‘Withdrawal’ turns towards isolation and remembered happiness. These contrasting poems place delight beside vulnerability."],sources=[source('Boloji — Ramesh Anand reviews Letters to Him','https://www.boloji.com/articles/15740/letters-to-him-by-gargi-saha',['Both collection titles and dates; Puthipatra2012; review characterizes prayer, questions and gratitude.']),source('Literary Vibes147 — Gargi Saha, November2024','https://positivevibes.today/article/newsview/569',['Published poem and biography confirm both collection titles.'],'search_index')],identity_match='Both distinctive collection titles and dates match captured biography; journal publication confirms writer identity beyond shared name.',poems_read=[dict(id=i,title=t,basis=b) for i,t,b in [(114,'The Sea','Full original read: sea changes as destiny, hopes and human scale; stray HTML fragment not treated as verse.'),(294,'A Tribute to Jayanta Mahapatra','Full original read: elegy using physics and stars; source award wording is inaccurate/incomplete and is not adopted as biographical fact.'),(600,'Onomatopoeia','Full original read: catalogue of natural and human sounds.'),(613,'Ineffable Altruism','Full original read: nature’s gifts and human destruction.'),(638,'The Simple Pleasures of Life','Full original read: birds, sheep, rain, light and renewed delight.'),(800,'Withdrawal','Full original read: isolation, difficulties engaging with others and memory; no medical or personal inference.')]],limitations=['Captured location Pune and another anthology’s Varanasi differ; no current residence stated.','Unverified awards omitted.','Poem294 says first Indian Sahitya Akademi recipient; do not propagate that unqualified claim. Original untouched.','No verified publisher/retailer product link added.'],next_action='Independent author/editor review; clarify current biographical location if desired, and flag poem294 award wording to editors without rewriting source.'))
